'use strict';
// PLAN 4 (bake from published) r3 §8.2 — the ADDITIVE, EDIT-PRESERVING migration of the menu's display structure into the
// SOURCE STORE (restaurants/{rid}/meta/source). Never today's whole-source seedSourceStore, which would replace a merchant's
// draft with the bootstrap.
//
// Driven by the reviewed data file tools/migrations/2026-10-26-menu-structure.json (generated by
// tools/migrations/gen-menu-structure-2026-10-26.js). For each restaurant:
//   1. readSource → { source, revision } (validated; a missing or malformed draft refuses)
//   2. ADD only fields that are ABSENT
//   3. a field PRESENT with a DIFFERENT value is a merchant edit: preserved, reported, never overwritten
//      (a data row whose dish / extra is no longer in the draft is reported too — nothing is invented)
//   4. validateSource on the result — an invalid result refuses and writes nothing
//   5. write the whole document in a TRANSACTION that re-reads the draft and compares its revision EXPLICITLY. A merchant
//      save in between makes it refuse (`migrate_menu_structure_moved`); the CLI then re-reads and re-plans (3 tries).
//      Not set({ lastUpdateTime }) — Firestore ignores a precondition on set() — and not update(), which merges; see
//      tools/migrate-catalog-display.js upgradeDraftInPlace, the measured pattern this follows.
// It never publishes: after --write the OWNER publishes once through the portal (§8.2 "Then").
//
// Run (dry run, the default — writes nothing):   node tools/migrate-menu-structure.js --project xpizza-delivery
// Write (the OWNER, or the advisor with the owner's approval — never an executor):  … --project xpizza-delivery --write
const { readSource, validateSource, sourceRefOf, encodeUpdateTime, canonicalize } = require('../catalog/source-store');
const { stampPlatformPending } = require('../catalog/platform-pending');   // F-1 (2026-11-07): Sherpa-written draft fields are stamped
const { candidateSource } = require('../catalog/candidate-validate');

const MAX_TRIES = 3;
const clone = (v) => JSON.parse(JSON.stringify(v));
const same = (a, b) => JSON.stringify(canonicalize(a)) === JSON.stringify(canonicalize(b));
const has = (o, k) => !!o && typeof o === 'object' && Object.prototype.hasOwnProperty.call(o, k);

// PURE. → { source (the planned document), added: [path], preserved: [{ path, have, want }], missing: [path] }
function planMigration(rid, source, rows) {
  const next = clone(source);
  const added = []; const preserved = []; const missing = [];
  const apply = (target, field, want, at) => {
    if (!has(target, field)) { target[field] = clone(want); added.push(at); return; }
    if (!same(target[field], want)) preserved.push({ path: at, have: target[field], want });
  };
  const r = rows || {};
  for (const [field, want] of Object.entries(r.structure || {})) apply(next.structure, field, want, `structure.${field}`);
  for (const [coll, label] of [['items', 'item'], ['extras', 'extra']]) {
    for (const [key, row] of Object.entries(r[coll] || {})) {
      const rec = (next[coll] || []).find((x) => x && x.key === key);
      for (const [field, want] of Object.entries((row && row.display) || {})) {
        const at = `${label}[${key}].display.${field}`;
        if (!rec || !rec.display || typeof rec.display !== 'object') { missing.push(at); continue; }
        apply(rec.display, field, want, at);
      }
    }
  }
  validateSource(next, rid);   // THROWS on an invalid result — nothing is written
  return { source: next, added, preserved, missing };
}

// The LIVE source (what is serving), for the platform-pending stamp: fields live already carries are not stamped. null when
// nothing is published (every added field is then stamped).
async function readLiveSource(db, rid) {
  const { getActiveVersionId } = require('../catalog/catalog-firestore');
  const { previewVersion } = require('../catalog/catalog-publish');
  const versionId = await getActiveVersionId(db, rid);
  if (versionId == null) return null;
  const p = await previewVersion(db, rid, versionId);
  return candidateSource(rid, { items: p.items, extras: p.extras, structure: p.structure });
}

// One restaurant: read → plan → (write in a revision-checked transaction). Re-plans on a concurrent save.
// F-1: the SAME transaction stamps the added fields as PLATFORM-PENDING (catalog/platform-pending), so a merchant reset cannot
// discard them while live does not carry them yet.
async function migrateRestaurant(db, rid, rows, { write = false, log = () => {}, readLive = readLiveSource } = {}) {
  for (let attempt = 1; attempt <= MAX_TRIES; attempt += 1) {
    const { source, revision } = await readSource(db, rid);
    const plan = planMigration(rid, source, rows);
    const report = { rid, revision, added: plan.added, preserved: plan.preserved, missing: plan.missing, written: false, attempt };
    if (!plan.added.length || !write) return report;
    const live = await readLive(db, rid);
    try {
      await db.runTransaction(async (tx) => {
        const now = await tx.get(sourceRefOf(db, rid));
        const nowRevision = now.exists ? encodeUpdateTime(now.updateTime) : null;
        if (nowRevision !== revision) {
          const e = new Error(`migrate_menu_structure_moved: ${rid} — the draft was at ${JSON.stringify(revision)} when this plan was computed and is at ${JSON.stringify(nowRevision)} now; a merchant saved in between`);
          e.code = 'migrate_menu_structure_moved';
          throw e;
        }
        // reads before writes (Firestore): the stamp reads its doc, then both writes land in this one transaction
        report.stamped = (await stampPlatformPending(tx, { db, rid, by: 'migrate-menu-structure', fields: plan.added, live })).stamped;
        tx.set(sourceRefOf(db, rid), canonicalize(plan.source));
      });
      report.written = true;
      return report;
    } catch (e) {
      if (e && e.code === 'migrate_menu_structure_moved' && attempt < MAX_TRIES) { log(`  ${rid}: ${e.message} — re-reading and re-planning`); continue; }
      throw e;
    }
  }
  throw new Error(`migrate_menu_structure_unreachable: ${rid}`);
}

async function migrateMenuStructure(db, data, opts = {}) {
  const out = [];
  for (const rid of Object.keys((data && data.restaurants) || {}).sort()) out.push(await migrateRestaurant(db, rid, data.restaurants[rid], opts));
  return out;
}

// ── --publish: the ADMIN publish of LIVE + the reviewed rows (PROPOSAL-plan4-migration-publish-path.md, advisor-approved 2026-11-02).
// §8.2's «the owner publishes once through the portal» cannot work: every portal publish goes through compareToActive
// (catalog/add-product.js:402), which refuses a new structure field (:568) and any display change on an existing dish (:422-427) —
// exactly what this migration adds. So, the Portal 1A Task 8 pattern (tools/migrate-catalog-display.js): the candidate is the
// LIVE version — projected to a source document exactly as «Volver al menú publicado» projects it (catalog/reset-draft.js:46) —
// plus ONLY the rows whose field is ABSENT live. Never the draft (a merchant's pending edits must not ride along), never the code
// tables (prices come from what is live). It publishes with an activeVersionId CAS (a concurrent publish refuses), and a run with
// nothing to add is `already_current` — no new version, no fence advance (the publish-version.js E-1 lesson).
const PUBLISH_SHA = 'plan4-migrate-publish';
const refusePublish = (code, detail) => { const e = new Error(`${code}: ${detail}`); e.code = code; throw e; };

async function captureLiveSource(db, rid) {
  const { getActiveVersionId } = require('../catalog/catalog-firestore');
  const { previewVersion } = require('../catalog/catalog-publish');
  const { candidateSource } = require('../catalog/candidate-validate');
  const versionId = await getActiveVersionId(db, rid);
  if (versionId == null) refusePublish('publish_refused_no_active_version', `${rid} — nothing is published`);
  // fail closed on photos: publishVersion carries a photo map only when its input brings one; this path brings none, so a live
  // version that HAS one would lose it. Photos are dark at this train — the refusal states it if that ever changes.
  const photos = await db.collection('restaurants').doc(rid).collection('versions').doc(versionId).collection('meta').doc('photos').get();
  if (photos.exists && Object.keys(photos.data() || {}).length) refusePublish('publish_refused_active_photos', `${rid}/${versionId} carries a photo map; this path would drop it`);
  const preview = await previewVersion(db, rid, versionId);
  // the source document «Volver al menú publicado» would write (reset-draft.js:46) — it is ALSO the published payload, unrebuilt:
  // previewVersion's items / extras / structure ARE the publish input of the live version, canonically (verified on both brands)
  const source = canonicalize(candidateSource(rid, { items: preview.items, extras: preview.extras, structure: preview.structure }));
  validateSource(source, rid);
  return { versionId, source, live: payloadOf(source) };
}
// Codex r1 P1: the candidate is NEVER rebuilt. Rebuilding (sourceToBuildInputs → buildCatalogV2) drops fields the builder does
// not carry back (a La Musa pickup_only_cats gate, an extra's has_photo), and comparing two rebuilt sides hid that IDENTICAL loss.
// So the publish input is the CAPTURED LIVE payload itself, with only the absent rows inserted by planMigration (which clones and
// adds, nothing else). The extras price table is the live records' own key → price.
function payloadOf(source) {
  const extras = {}; for (const e of source.extras || []) extras[e.key] = e.price;
  return { items: source.items, structure: source.structure, extras, extraRecords: source.extras, source_sha: PUBLISH_SHA };
}
// The candidate may differ from the CAPTURED LIVE payload ONLY by the added fields: strip exactly them and the two must be canonically
// EQUAL — prices, keys, order, categories, gates, has_photo, every other field. Anything else refuses before a write.
function assertOnlyAdded(rid, liveIn, nextIn, added) {
  const strip = clone(nextIn);
  for (const at of added) {
    const m = /^structure\.(.+)$/.exec(at) || null;
    if (m) { delete strip.structure[m[1]]; continue; }
    const r = /^(item|extra)\[(.+)\]\.display\.(.+)$/.exec(at);
    if (!r) refusePublish('publish_refused_unexpected_delta', `${rid} — unrecognised added path ${at}`);
    const rec = (r[1] === 'item' ? strip.items : strip.extraRecords).find((x) => x && x.key === r[2]);
    if (!rec || !rec.display) refusePublish('publish_refused_unexpected_delta', `${rid} — ${at} has no record in the candidate`);
    delete rec.display[r[3]];
  }
  if (!same(strip, liveIn)) refusePublish('publish_refused_unexpected_delta', `${rid} — the candidate differs from live beyond the ${added.length} migrated field(s)`);
}

// F-1 r2 (Codex r1 P1-1): a successful publish (or an already-current re-run) is where live comes to CARRY the stamped fields, so the
// platform-pending stamp is resolved HERE — otherwise it outlives the publish and a LATER rollback relocks the draft. Retryable: a
// failed cleanup never undoes the publish; re-running --publish --apply (already_current = no new version) retries it.
async function cleanupStamp(db, rid, liveSource) {
  try {
    const r = await require('../catalog/platform-pending').resolvePlatformPending(db, rid, liveSource);
    return r.cleared ? 'cleared' : (r.pending ? 'still_pending' : 'none');
  } catch (e) {
    return 'cleanup_failed';
  }
}

async function publishRestaurant(db, rid, rows, { apply = false, mirror } = {}) {
  const { versionId, source, live } = await captureLiveSource(db, rid);
  const plan = planMigration(rid, source, rows);   // the SAME absent-only planner as --write; validateSource inside
  const report = { rid, liveVersion: versionId, added: plan.added, preserved: plan.preserved, missing: plan.missing, published: null, outcome: null };
  if (!plan.added.length) { report.outcome = 'already_current'; if (apply) report.stamp = await cleanupStamp(db, rid, source); return report; }
  const next = payloadOf(plan.source);
  assertOnlyAdded(rid, live, next, plan.added);   // stripped candidate vs the CAPTURED live payload (not a rebuild)
  if (!apply) { report.outcome = 'dry_run'; return report; }
  const { publishVersion } = require('../catalog/catalog-publish');
  const res = await publishVersion(db, rid, next, { mirror, expected: { activeVersionId: versionId } });   // CAS: a concurrent publish refuses
  report.published = res.versionId; report.outcome = 'published';
  report.stamp = await cleanupStamp(db, rid, plan.source);   // live now IS the candidate
  return report;
}
async function publishMenuStructure(db, data, opts = {}) {
  const out = [];
  for (const rid of Object.keys((data && data.restaurants) || {}).sort()) out.push(await publishRestaurant(db, rid, data.restaurants[rid], opts));
  return out;
}

module.exports = { planMigration, migrateRestaurant, migrateMenuStructure, readLiveSource, MAX_TRIES, captureLiveSource, publishRestaurant, publishMenuStructure, assertOnlyAdded };

if (require.main === module) {
  try { require('dotenv').config(); } catch (_) { /* devDependency */ }
  const admin = require('firebase-admin');
  const { requireProject } = require('./require-project');
  const { RTDB_URL } = require('../catalog/mirror-rtdb');
  const DATA = require('./migrations/2026-10-26-menu-structure.json');
  const WRITE = process.argv.includes('--write');
  const PUBLISH = process.argv.includes('--publish'); const APPLY = process.argv.includes('--apply');
  if (WRITE && PUBLISH) { console.error('menu structure migration: REFUSED — --write (the draft) and --publish (live) are separate runs'); process.exit(2); }
  if (APPLY && !PUBLISH) { console.error('menu structure migration: REFUSED — --apply belongs to --publish'); process.exit(2); }
  // THE PROJECT GUARD, before anything resolves a credential or constructs a client: --project is mandatory.
  const PROJECT_ID = requireProject({ requireFlag: true });
  admin.initializeApp({ credential: admin.credential.applicationDefault(), projectId: PROJECT_ID, databaseURL: RTDB_URL });
  if (PUBLISH) {
    // node tools/migrate-menu-structure.js --project xpizza-delivery --publish [--apply]   (DRY by default; --apply is the OWNER's)
    const { makeRtdbMirror } = require('../catalog/mirror-rtdb');
    console.log(APPLY ? 'MENU STRUCTURE PUBLISH — PUBLISHING live + the absent rows (owner)' : 'MENU STRUCTURE PUBLISH — DRY RUN (publishes nothing)');
    publishMenuStructure(admin.firestore(), DATA, { apply: APPLY, mirror: makeRtdbMirror(admin.database()) })
      .then((reports) => {
        for (const r of reports) {
          console.log(`  ${r.rid} (live ${r.liveVersion}): ${r.outcome}${r.published ? ` → ${r.published}` : ''}; ${r.added.length} to add; ${r.preserved.length} live value(s) preserved; ${r.missing.length} row(s) with no target; prices / keys / order identical to live (asserted)`);
          for (const p of r.added) console.log(`    + ${p}`);
          for (const p of r.preserved) console.log(`    = ${p.path} kept ${JSON.stringify(p.have)} (data says ${JSON.stringify(p.want)})`);
          for (const p of r.missing) console.log(`    ? ${p} — not live, skipped`);
          if (r.stamp) console.log(`    platform-pending stamp: ${r.stamp}${r.stamp === 'cleanup_failed' ? ' — re-run --publish --apply to retry (already_current publishes nothing)' : ''}`);
        }
        // Codex r1 P1: NOT an unconditional «Volver al menú publicado» — it would discard a merchant's pending edits. The draft gets the
        // revision-checked, absent-only --write (merchant edits preserved); the reset only for a draft reviewed as disposable.
        console.log(APPLY ? 'NEXT: `--write` (DRY first) so each DRAFT carries the published fields — absent-only, revision-checked, pending merchant edits kept (NOT a reset); then have anyone with the portal open REFRESH it; then the read-only getPublicMenu verify, then form-bundle-live-check.' : 'nothing published. --apply is the owner\'s.');
        process.exit(0);
      })
      .catch((e) => { console.error('menu structure publish failed (nothing published for the restaurant that failed):', e && e.message); process.exit(1); });
    return;
  }
  console.log(WRITE ? 'MENU STRUCTURE MIGRATION — WRITING the source store (nothing is published)' : 'MENU STRUCTURE MIGRATION — DRY RUN (writes nothing)');
  migrateMenuStructure(admin.firestore(), DATA, { write: WRITE, log: (l) => console.log(l) })
    .then((reports) => {
      for (const r of reports) {
        console.log(`  ${r.rid} (draft ${r.revision}): ${r.added.length} to add${r.written ? ' — WRITTEN' : ''}; ${r.preserved.length} merchant value(s) preserved; ${r.missing.length} row(s) with no target`);
        for (const p of r.added) console.log(`    + ${p}`);
        for (const p of r.preserved) console.log(`    = ${p.path} kept ${JSON.stringify(p.have)} (data says ${JSON.stringify(p.want)})`);
        for (const p of r.missing) console.log(`    ? ${p} — not in the draft, skipped`);
        if (r.written) console.log(`    stamped platform-pending (live lacks them; a merchant reset is refused until published): ${(r.stamped || []).length}`);
      }
      console.log(WRITE ? 'NEXT: the owner publishes once through the portal, then the read-only getPublicMenu verification.' : 'nothing written. --write is the owner\'s.');
      process.exit(0);
    })
    .catch((e) => { console.error('menu structure migration failed (nothing written for the restaurant that failed):', e && e.message); process.exit(1); });
}
